pub fn hasNoMorePendingLifecycleScripts(client: *PackageManager) bool {
        _ = client.reportSlowLifecycleScripts();
        return (client.pending_lifecycle_script_tasks.load(.monotonic) == 0);
}

pub fn tickLifecycleScripts(client: *PackageManager) void {
        _ = client.event_loop.tickOnce(client);
}

pub fn sleep(client: *PackageManager) void {
        _ = client.reportSlowLifecycleScripts();
        _ = Output.flush();
        _ = client.event_loop.tick(client, hasNoMorePendingLifecycleScripts);
}

pub fn reportSlowLifecycleScripts(client: *PackageManager) void {
        const log_level = client.options.log_level;
        if ((log_level == .silent)) {
            return;
        }
        if (bun.feature_flag.BUN_DISABLE_SLOW_LIFECYCLE_SCRIPT_LOGGING.get()) {
            return;
        }
        if (client.active_lifecycle_scripts.peek()) |active_lifecycle_script_running_for_the_longest_amount_of_time| {
            _ = &active_lifecycle_script_running_for_the_longest_amount_of_time;
            if ((client.cached_tick_for_slow_lifecycle_script_logging == client.event_loop.iterationNumber())) {
                return;
            }
            client.cached_tick_for_slow_lifecycle_script_logging = client.event_loop.iterationNumber();
            const current_time = bun.timespec.now(.allow_mocked_time).ns();
            const time_running = (current_time -| active_lifecycle_script_running_for_the_longest_amount_of_time.started_at);
            const interval: u64 = (if (log_level.isVerbose()) (std.time.ns_per_s * 5) else (std.time.ns_per_s * 30));
            if (((time_running > interval) and ((current_time -| client.last_reported_slow_lifecycle_script_at) > interval))) {
                client.last_reported_slow_lifecycle_script_at = current_time;
                const package_name = active_lifecycle_script_running_for_the_longest_amount_of_time.package_name;
                if ((!((package_name.len > 1) and (package_name[@as(usize, @intCast((package_name.len - 1)))] == 115)))) {
                    _ = Output.warn("{s}'s postinstall cost you {f}\n", .{ package_name, bun.fmt.fmtDurationOneDecimal(time_running) });
                } else {
                    _ = Output.warn("{s}' postinstall cost you {f}\n", .{ package_name, bun.fmt.fmtDurationOneDecimal(time_running) });
                }
                _ = Output.flush();
            }
        }
}

